import fs from 'node:fs/promises';
import path from 'node:path';
import {createHash} from 'node:crypto';
import sharp from 'sharp';
sharp.cache(false);
const [id,source,view='main']=process.argv.slice(2);
const base='data/vtt/biomes-20261015';
const plan=JSON.parse(await fs.readFile(base+'/plan.json','utf8'));
const spec=plan.items.find(a=>a.id===id);if(!spec||!['main','interior'].includes(view))throw Error('Unknown asset or view');
const meta=await sharp(source).metadata(),stats=await sharp(source).stats();
if(spec.type!=='paint'&&(!meta.hasAlpha||stats.isOpaque))throw Error('True alpha required');
const building=spec.type==='building',paint=spec.type==='paint';
let pipeline=sharp(source);
if(!building&&!paint)pipeline=pipeline.trim({threshold:4});
if(paint)pipeline=pipeline.resize(1024,1024).removeAlpha();
else pipeline=pipeline.resize({width:building?1024:768,height:building?1024:768,fit:'inside'});
const bytes=await pipeline.webp({quality:95,alphaQuality:100}).toBuffer();
const packed=await sharp(bytes).metadata();
const stem=id+(view==='interior'?'-interior':'');
const directory='public/vtt/biomes-20261015';await fs.mkdir(directory,{recursive:true});await fs.mkdir(base+'/completed',{recursive:true});
const image='/vtt/biomes-20261015/'+stem+'.webp',thumbnail='/vtt/biomes-20261015/'+stem+'-thumb.webp';
await fs.writeFile('public'+image,bytes);await fs.writeFile('public'+thumbnail,await sharp(bytes).resize({width:192,height:192,fit:'inside'}).webp({quality:88,alphaQuality:100}).toBuffer());
const recordPath=base+'/completed/'+id+'.json';const old=JSON.parse(await fs.readFile(recordPath,'utf8').catch(()=>'{"outputs":{}}'));
const longest=spec.sizeMetres/plan.humanGridMetres;
const output={image,thumbnail,pixelWidth:packed.width,pixelHeight:packed.height,sha256:createHash('sha256').update(bytes).digest('hex'),sourceBasename:path.basename(source),generator:'built-in image_gen',width:building?longest:Number((longest*packed.width/Math.max(packed.width,packed.height)).toFixed(4)),height:building?longest:Number((longest*packed.height/Math.max(packed.width,packed.height)).toFixed(4)),hasAlpha:!paint};
const record={...spec,status:'generated',outputs:{...old.outputs,[view]:output}};await fs.writeFile(recordPath,JSON.stringify(record,null,2)+'\n');console.log(JSON.stringify({id,view,pixels:[packed.width,packed.height],width:output.width,height:output.height}));
